"""Structured user interactions generated by UI controls.

They are deterministic and are never interpreted by the LLM.
"""

from dataclasses import dataclass
from uuid import UUID


@dataclass(frozen=True)
class Confirm:
    """Confirm the operation waiting for confirmation whose confirmation
    request is ``operation_id``."""

    operation_id: UUID


@dataclass(frozen=True)
class Cancel:
    """Cancel the pending operation."""


@dataclass(frozen=True)
class SelectCard:
    """Select the card of the card operation being collected."""

    card_id: UUID


type Interaction = Confirm | Cancel | SelectCard
